process ANGSD_DOSAF {
    tag "$meta.id"
    label 'process_medium'

    conda "${moduleDir}/environment.yml"
    container "${workflow.containerEngine in ['singularity', 'apptainer'] && !task.ext.singularity_pull_docker_container
        ? 'https://community-cr-prod.seqera.io/docker/registry/v2/blobs/sha256/63/639ce33ed86c005c940303a12fc487291ffdd096934afc1fa14dd8f45c831e3b/data'
        : 'community.wave.seqera.io/library/angsd_htslib:2b83a6f633f30127'}"

    input:
    tuple val(meta), path(bams), path(bam_indices)
    tuple path(reference_fasta), path(reference_fai)
    tuple path(ancestral_fasta), path(ancestral_fai) // Optional. Provides ancestral state for unfolded SFS.
    path(error_file) // Optional. Required for SYK model (-GL 4) only.
    path(inbreeding_coefficients) // Optional. Required for -doSAF 2 (inbreeding-aware mode).
    path(soapsnp_calibration) // Optional. Required for -GL 3.
    val(gl_model)
    val(dosaf_mode)

    output:
    tuple val(meta), path("*.saf.idx"), path("*.saf.pos.gz"), path("*.saf.gz"), emit: saf
    tuple val("${task.process}"), val('angsd'), eval("angsd 2>&1 | sed '1!d;s/.*version: //;s/ .*//'"), emit: versions_angsd, topic: versions

    when:
    task.ext.when == null || task.ext.when

    script:
    def args   = task.ext.args ?: ''
    def prefix = task.ext.prefix ?: "${meta.id}"

    // Validate GL model
    if (!(gl_model in [1, 2, 3, 4])) {
        error(
            "ANGSD_DOSAF: Invalid GL model '${gl_model}'. Please pass one of 1, 2, 3, or 4 as the gl_model input."
            )
    }

    // Validate doSAF mode
    if (!(dosaf_mode in [1, 2])) {
        error(
            "ANGSD_DOSAF: Invalid doSAF mode '${dosaf_mode}'. Please pass 1 or 2 as the dosaf_mode input."
            )
    }

    // Validate doSAF 2 has inbreeding coefficients
    if (dosaf_mode == 2 && !inbreeding_coefficients) {
        error(
            "ANGSD_DOSAF: -doSAF 2 requires inbreeding coefficients (indF). Please supply an inbreeding_coefficients file."
            )
    }

    // Validate doSAF 2 called alongside -doMajoMinor and -doMaf
    if (dosaf_mode == 2 && !(args.contains("-doMajorMinor"))) {
        error(
            "ANGSD_DOSAF: -doSAF 2 requires -doMajorMinor to be specified. Please include in ext.args."
            )
    }
    if (dosaf_mode == 2 && !(args.contains("-doMaf"))) {
        error(
            "ANGSD_DOSAF: -doSAF 2 requires -doMaf to be specified. Please include in ext.args."
            )
    }

    // Validate soapsnp calibration directory provided when using -GL 3
    if (gl_model == 3 && !soapsnp_calibration) {
        error(
            "ANGSD_DOSAF: -GL 3 (soapSNP model) requires calibration directory. Please supply directory."
        )
    }

    // Validate GL 4 has error file
    if (gl_model == 4 && !error_file) {
        error(
            "ANGSD_DOSAF: -GL 4 (SYK model) requires an error file. Please supply an error_file."
            )
    }

    // Compute -minInd dynamically as a fraction of the population's BAM list size
    // Default set to 0 as this mimics angsd default for minInd
    def frac        = (task.ext.args2 ?: '0') as Double
    def n_samples   = bams instanceof List ? bams.size() : 1
    def min_ind_arg = frac > 0 ? "-minInd ${Math.ceil(n_samples * frac).toInteger()}" : ''

    // Touch fai indices to ensure they are newer than their fasta (ANGSD requirement)
    def touch_ref = reference_fai  ? "sleep 1 && touch ${reference_fai}"  : ''
    def touch_anc = ancestral_fai  ? "sleep 1 && touch ${ancestral_fai}"  : ''

    // Reference / ancestral args.
    // If ancestral_fasta supplied: use as -anc and pass reference as -ref.
    // If not supplied: use reference as -anc and -ref (suitable for folded SFS via realSFS -fold 1).
    def ref_anc_arg = ancestral_fasta ? "-anc ${ancestral_fasta} -ref ${reference_fasta}" : "-anc ${reference_fasta} -ref ${reference_fasta}"

    // Optional args
    def indF_arg   = inbreeding_coefficients ? "-indF ${inbreeding_coefficients}" : ""
    def errors_arg = error_file              ? "-errors ${error_file}"            : ""

    // SOAPsnp model (-GL 3) needs to know the name of the temp directory
    def gl3_args = gl_model == 3 ? "-tmpdir ${soapsnp_calibration}" : ""

    // SYK model (-GL 4) needs an error file and -doCounts 1
    def gl4_args = gl_model == 4 ? "${errors_arg} -doCounts 1" : ""

    """
    ${touch_ref}
    ${touch_anc}
    printf '%s\\n' ${bams} > bamlist.txt

    angsd \\
        -nThreads ${task.cpus} \\
        -bam bamlist.txt \\
        -GL ${gl_model} \\
        -doSAF ${dosaf_mode} \\
        ${ref_anc_arg} \\
        ${indF_arg} \\
        ${gl3_args} \\
        ${gl4_args} \\
        ${args} \\
        ${min_ind_arg} \\
        -out ${prefix}
    """

    stub:
    def prefix = task.ext.prefix ?: "${meta.id}"
    """
    touch ${prefix}.saf.idx
    echo "" | gzip > ${prefix}.saf.pos.gz
    echo "" | gzip > ${prefix}.saf.gz
    """
}

nextflow_process {

    name "Test Process ANGSD_DOSAF"
    script "../main.nf"
    process "ANGSD_DOSAF"

    tag "modules"
    tag "modules_nfcore"
    tag "angsd"
    tag "angsd/dosaf"


    // -------------------------------------------------------------------------
    // SUCCESS CASE 1: GL 1; doSAF 1; no ancestral
    // -------------------------------------------------------------------------

    test("angsd - GL 1 - doSAF 1") {
        config "./nextflow.config"

        when {
            params {
                angsd_args   = '-r chr20:1400000-1500000 -checkBamHeaders 0'
                min_ind_frac = 0
            }
            process {
                """
                input[0] = [
                    [
                        id: "FIN",
                        population: "FIN",
                        samples: ["HG00349", "HG00358", "HG00350", "HG00351"]
                    ],
                    [
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/HG00349.chr20_1400000-1500000.bam"),
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/HG00350.chr20_1400000-1500000.bam"),
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/HG00351.chr20_1400000-1500000.bam"),
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/HG00358.chr20_1400000-1500000.bam")
                    ],
                    [
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/HG00349.chr20_1400000-1500000.bam.bai"),
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/HG00350.chr20_1400000-1500000.bam.bai"),
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/HG00351.chr20_1400000-1500000.bam.bai"),
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/HG00358.chr20_1400000-1500000.bam.bai")
                    ]
                ]
                input[1] = [
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/chr20/sequence/GRCh38_chr20_1_2000000.fasta.gz'),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/chr20/sequence/GRCh38_chr20_1_2000000.fasta.gz.fai')
                ]
                input[2] = [ [], [] ]
                input[3] = []
                input[4] = []
                input[5] = []
                input[6] = 1
                input[7] = 1
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }


    // -------------------------------------------------------------------------
    // SUCCESS CASE 2: GL 1; doSAF 2; no ancestral
    // -------------------------------------------------------------------------

    test("angsd - GL 1 - doSAF 2") {
        config "./nextflow.config"

        setup{
            new File("${launchDir}/angsd_FIN.indF").text = "0.0\n0.0\n0.01\n0.017\n"
        }

        when {
            params {
                angsd_args   = '-doMajorMinor 1 -doMaf 1 -r chr20:1400000-1500000 -checkBamHeaders 0'
                min_ind_frac = 0
            }
            process {
                """
                input[0] = [
                    [
                        id: "FIN",
                        population: "FIN",
                        samples: ["HG00349", "HG00358", "HG00350", "HG00351"]
                    ],
                    [
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/HG00349.chr20_1400000-1500000.bam"),
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/HG00350.chr20_1400000-1500000.bam"),
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/HG00351.chr20_1400000-1500000.bam"),
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/HG00358.chr20_1400000-1500000.bam")
                    ],
                    [
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/HG00349.chr20_1400000-1500000.bam.bai"),
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/HG00350.chr20_1400000-1500000.bam.bai"),
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/HG00351.chr20_1400000-1500000.bam.bai"),
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/HG00358.chr20_1400000-1500000.bam.bai")
                    ]
                ]
                input[1] = [
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/chr20/sequence/GRCh38_chr20_1_2000000.fasta.gz'),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/chr20/sequence/GRCh38_chr20_1_2000000.fasta.gz.fai')
                ]
                input[2] = [ [], [] ]
                input[3] = []
                input[4] = file("${launchDir}/angsd_FIN.indF", checkIfExists: true)
                input[5] = []
                input[6] = 1
                input[7] = 2
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }


    // -------------------------------------------------------------------------
    // SUCCESS CASE 3: GL 3; doSAF 1; no ancestral
    // -------------------------------------------------------------------------

    test("angsd - GL3 - doSAF1") {
        config "./nextflow.config"

        setup {
            // Nextflow can't stage a directory straight off raw.githubusercontent.com,
            // so pull the individual calibration-matrix files down and reassemble
            // them into a local folder for the test to use.
            def calibDir = new File("${launchDir}/soapsnp_calibration_matrix")
            calibDir.mkdirs()
            def base = "https://raw.githubusercontent.com/nf-core/test-datasets/modules/data/delete_me/angsd/soapsnp_calibration_matrix/"
            [
                "0.counts0", "0.qual0",
                "1.counts1", "1.qual1",
                "2.counts2", "2.qual2",
                "3.counts3", "3.qual3"
            ].each { fname ->
                new File("${calibDir}/${fname}").bytes = new URL("${base}${fname}").bytes
            }
        }

        when {
            params {
                angsd_args   = '-r chr20:1400000-1500000 -checkBamHeaders 0'
                min_ind_frac = 0
            }

            process {
                """
                input[0] = [
                    [
                        id: "FIN",
                        population: "FIN",
                        samples: ["HG00349", "HG00358", "HG00350", "HG00351"]
                    ],
                    [
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/HG00349.chr20_1400000-1500000.bam"),
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/HG00350.chr20_1400000-1500000.bam"),
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/HG00351.chr20_1400000-1500000.bam"),
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/HG00358.chr20_1400000-1500000.bam")
                    ],
                    [
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/HG00349.chr20_1400000-1500000.bam.bai"),
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/HG00350.chr20_1400000-1500000.bam.bai"),
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/HG00351.chr20_1400000-1500000.bam.bai"),
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/HG00358.chr20_1400000-1500000.bam.bai")
                    ]
                ]
                input[1] = [
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/chr20/sequence/GRCh38_chr20_1_2000000.fasta.gz'),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/chr20/sequence/GRCh38_chr20_1_2000000.fasta.gz.fai')
                ]
                input[2] = [ [], [] ]
                input[3] = []
                input[4] = []
                input[5] = [ file("${launchDir}/soapsnp_calibration_matrix") ]
                input[6] = 3
                input[7] = 1
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }


    // -------------------------------------------------------------------------
    // SUCCESS CASE 4: GL 4 (requires error file)
    // -------------------------------------------------------------------------

    test("angsd - GL4") {
        config "./nextflow.config"

        setup {
            new File("${launchDir}/angsd_syk.errors").text = "0.000000\t0.005488\t0.003847\t0.003137\t0.006807\t0.000000\t0.001972\t0.002396\t0.002190\t0.001855\t0.000000\t0.008068\t0.002491\t0.004268\t0.005812\t0.000000\n"
        }

        when {
            params {
                angsd_args   = '-r chr20:1400000-1500000 -checkBamHeaders 0'
                min_ind_frac = 0
            }

            process {
                """
                input[0] = [
                    [
                        id: "FIN",
                        population: "FIN",
                        samples: ["HG00349", "HG00358", "HG00350", "HG00351"]
                    ],
                    [
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/HG00349.chr20_1400000-1500000.bam"),
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/HG00350.chr20_1400000-1500000.bam"),
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/HG00351.chr20_1400000-1500000.bam"),
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/HG00358.chr20_1400000-1500000.bam")
                    ],
                    [
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/HG00349.chr20_1400000-1500000.bam.bai"),
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/HG00350.chr20_1400000-1500000.bam.bai"),
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/HG00351.chr20_1400000-1500000.bam.bai"),
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/HG00358.chr20_1400000-1500000.bam.bai")
                    ]
                ]
                input[1] = [
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/chr20/sequence/GRCh38_chr20_1_2000000.fasta.gz'),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/chr20/sequence/GRCh38_chr20_1_2000000.fasta.gz.fai')
                ]
                input[2] = [ [], [] ]
                input[3] = file("${launchDir}/angsd_syk.errors", checkIfExists: true)
                input[4] = []
                input[5] = []
                input[6] = 4
                input[7] = 1
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }


    // -------------------------------------------------------------------------
    // SUCCESS CASE 5: GL 1; doSAF 1; with ancestral FASTA
    // -------------------------------------------------------------------------

    test("angsd - GL 1 - doSAF 1 - with ancestral fasta") {
        config "./nextflow.config"

        when {
            params {
                angsd_args   = '-r chr20:1400000-1500000 -checkBamHeaders 0'
                min_ind_frac = 0
            }
            process {
                """
                input[0] = [
                    [
                        id: "FIN",
                        population: "FIN",
                        samples: ["HG00349", "HG00358", "HG00350", "HG00351"]
                    ],
                    [
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/HG00349.chr20_1400000-1500000.bam"),
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/HG00350.chr20_1400000-1500000.bam"),
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/HG00351.chr20_1400000-1500000.bam"),
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/HG00358.chr20_1400000-1500000.bam")
                    ],
                    [
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/HG00349.chr20_1400000-1500000.bam.bai"),
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/HG00350.chr20_1400000-1500000.bam.bai"),
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/HG00351.chr20_1400000-1500000.bam.bai"),
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/HG00358.chr20_1400000-1500000.bam.bai")
                    ]
                ]
                input[1] = [
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/chr20/sequence/GRCh38_chr20_1_2000000.fasta.gz'),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/chr20/sequence/GRCh38_chr20_1_2000000.fasta.gz.fai')
                ]
                input[2] = [
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/chr20/resources/homo_sapiens_ancestor_chr20_1_2000000.fasta.gz'),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/chr20/resources/homo_sapiens_ancestor_chr20_1_2000000.fasta.gz.fai')
                ]
                input[3] = []
                input[4] = []
                input[5] = []
                input[6] = 1
                input[7] = 1
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }


    // -------------------------------------------------------------------------
    // SUCCESS CASE 6: GL 1; doSAF 1; min_ind_frac > 0
    // -------------------------------------------------------------------------

    test("angsd - GL 1 - doSAF 1 - min_ind_frac") {
        config "./nextflow.config"

        when {
            params {
                angsd_args   = '-r chr20:1400000-1500000 -checkBamHeaders 0'
                min_ind_frac = 0.5
            }
            process {
                """
                input[0] = [
                    [
                        id: "FIN",
                        population: "FIN",
                        samples: ["HG00349", "HG00358", "HG00350", "HG00351"]
                    ],
                    [
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/HG00349.chr20_1400000-1500000.bam"),
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/HG00350.chr20_1400000-1500000.bam"),
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/HG00351.chr20_1400000-1500000.bam"),
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/HG00358.chr20_1400000-1500000.bam")
                    ],
                    [
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/HG00349.chr20_1400000-1500000.bam.bai"),
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/HG00350.chr20_1400000-1500000.bam.bai"),
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/HG00351.chr20_1400000-1500000.bam.bai"),
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/HG00358.chr20_1400000-1500000.bam.bai")
                    ]
                ]
                input[1] = [
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/chr20/sequence/GRCh38_chr20_1_2000000.fasta.gz'),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/chr20/sequence/GRCh38_chr20_1_2000000.fasta.gz.fai')
                ]
                input[2] = [ [], [] ]
                input[3] = []
                input[4] = []
                input[5] = []
                input[6] = 1
                input[7] = 1
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }


    // -------------------------------------------------------------------------
    // FAILURE CASE 1: Missing inbreeding coefficients file (needed for doSAF 2)
    // -------------------------------------------------------------------------

    test("angsd - GL1 - doSAF2 - missing inbreeding coefficients") {
        config "./nextflow.config"

        when {
            params {
                angsd_args   = '-r chr20:1400000-1500000 -checkBamHeaders 0'
                min_ind_frac = 0
            }
            process {
                """
                input[0] = [
                    [
                        id: "FIN",
                        population: "FIN",
                        samples: ["HG00349", "HG00358", "HG00350", "HG00351"]
                    ],
                    [
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/HG00349.chr20_1400000-1500000.bam"),
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/HG00350.chr20_1400000-1500000.bam"),
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/HG00351.chr20_1400000-1500000.bam"),
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/HG00358.chr20_1400000-1500000.bam")
                    ],
                    [
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/HG00349.chr20_1400000-1500000.bam.bai"),
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/HG00350.chr20_1400000-1500000.bam.bai"),
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/HG00351.chr20_1400000-1500000.bam.bai"),
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/HG00358.chr20_1400000-1500000.bam.bai")
                    ]
